18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Map;
23	import java.util.Objects;
24	
25	import jakarta.servlet.http.HttpServletRequest;
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.dao.DataIntegrityViolationException;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.HttpStatusCode;
32	import org.springframework.http.ProblemDetail;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
35	import org.springframework.security.access.AccessDeniedException;
36	import org.springframework.validation.BindingResult;
37	import org.springframework.validation.FieldError;
38	import org.springframework.web.bind.MethodArgumentNotValidException;
39	import org.springframework.web.bind.annotation.ControllerAdvice;
40	import org.springframework.web.bind.annotation.ExceptionHandler;
41	import org.springframework.web.bind.annotation.ResponseBody;
42	import org.springframework.web.context.request.ServletWebRequest;
43	import org.springframework.web.context.request.WebRequest;
44	import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;
45	
46	/**
47	 * Global Exception handler for REST controllers.
48	 * <p>
49	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
50	 * Every rejection is reported as an RFC&nbsp;7807 {@code application/problem+json} body carrying at least the
51	 * {@code type}, {@code title}, {@code status} and {@code detail} members.
52	 * <p>
53	 * By extending {@link ResponseEntityExceptionHandler} the framework-level exceptions (such as an unreadable
54	 * request body, a missing parameter or a type mismatch) are mapped to their proper {@code 4xx} status and
55	 * rendered with the same problem+json shape instead of falling through to the generic {@code 500} handler.
56	 *
57	 * @author Vitaliy Fedoriv
58	 * @author Alexander Dudkin
59	 */
60	@ControllerAdvice
61	public class ExceptionControllerAdvice extends ResponseEntityExceptionHandler {
62	
63	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
64	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
65	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
66	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
67	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the given identity key already exists";
68	    private static final String ERROR_CITY_AT_CAPACITY = "The given city already contains the maximum number of owners";
69	    private static final String ERROR_DAILY_LIMIT_REACHED = "The maximum number of owners has already been created today";
70	
71	    /**
72	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
73	     * class.
74	     *
75	     * @param e     Object referring to the thrown exception.
76	     * @param status HTTP response status.
77	     * @param url URL request.
78	     */
79	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
80	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
81	        problemDetail.setType(URI.create(url.toString()));
82	        problemDetail.setTitle(e.getClass().getSimpleName());
83	        problemDetail.setDetail(detail);
84	        problemDetail.setProperty("timestamp", Instant.now());
85	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
86	        return problemDetail;
87	    }
88	
89	    /**
90	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
91	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
92	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
93	     * would catch it and report an authorization failure as a 500.
94	     *
95	     * @param e The {@link AccessDeniedException} to propagate
96	     * @throws AccessDeniedException always
97	     */
98	    @ExceptionHandler(AccessDeniedException.class)
99	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
100	        throw e;
101	    }
102	
103	    /**
104	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
105	     *
106	     * @param e The {@link Exception} to be handled
107	     * @param request {@link HttpServletRequest} object referring to the current request.
108	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
109	     */
110	    @ExceptionHandler(Exception.class)
111	    @ResponseBody
112	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
113	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
114	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
115	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
116	        return ResponseEntity.status(status).body(detail);
117	    }
118	
119	    /**
120	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
121	     * method returns a 404 Not Found status if an entity does not exist.
122	     *
123	     * @param e The {@link DataIntegrityViolationException} to be handled
124	     * @param request {@link HttpServletRequest} object referring to the current request.
125	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
126	     */
127	    @ExceptionHandler(DataIntegrityViolationException.class)
128	    @ResponseBody
129	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
130	        logger.warn("Data integrity violation at {} {}: {}",
131	            request.getMethod(),
132	            request.getRequestURI(),
133	            e.getMessage());
134	        logger.debug("Data integrity violation stacktrace", e);
135	        HttpStatus status = HttpStatus.NOT_FOUND;
136	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
137	        return ResponseEntity.status(status).body(detail);
138	    }
139	
140	    /**
141	     * Handles exception thrown by Bean Validation on controller method bodies, overriding the default
142	     * {@link ResponseEntityExceptionHandler} behaviour so the resulting 400 Bad Request carries this
143	     * application's problem+json shape (including the {@code schemaValidationErrors} and {@code errors}
144	     * members) rather than the framework default.
145	     *
146	     * @param ex The {@link MethodArgumentNotValidException} to be handled
147	     * @param headers the headers to be written to the response
148	     * @param status the selected response status (400 Bad Request)
149	     * @param request the current request
150	     * @return A {@link ResponseEntity} containing the problem+json error information and a 400 Bad Request status.
151	     */
152	    @Override
153	    protected ResponseEntity<Object> handleMethodArgumentNotValid(MethodArgumentNotValidException ex,
154	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
155	        BindingResult bindingResult = ex.getBindingResult();
156	        ProblemDetail detail = ProblemDetail.forStatus(status);
157	        detail.setDetail(ERROR_INVALID_REQUEST);
158	        if (bindingResult.hasErrors()) {
159	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
160	                .map(fieldError -> {
161	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
162	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
163	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
164	                        fieldError.getField(),
165	                        defaultMessage,
166	                        rejectedValue);
167	                    return new ValidationMessageDto(message)
168	                        .putAdditionalProperty("field", fieldError.getField())
169	                        .putAdditionalProperty("rejectedValue", rejectedValue)
170	                        .putAdditionalProperty("defaultMessage", defaultMessage);
171	                })
172	                .toList();
173	            logger.debug("Validation error at {}: {}",
174	                request.getDescription(false),
175	                bindingResult.getFieldErrors());
176	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
177	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
178	                .map(FieldError::getField)
179	                .distinct()
180	                .toList();
181	            detail.setProperty("errors", invalidFields);
182	        }
183	        return this.handleExceptionInternal(ex, detail, headers, status, request);
184	    }
185	
186	    /**
187	     * Central rendering hook for every exception handled by {@link ResponseEntityExceptionHandler}
188	     * (unreadable bodies, missing parameters, type mismatches, unsupported media types, and so on).
189	     * It normalises the body into this application's problem+json shape, guaranteeing the {@code type},
190	     * {@code title}, {@code status} and {@code detail} members are present while preserving any
191	     * problem detail already prepared by a more specific handler.
192	     *
193	     * @param ex the exception being handled
194	     * @param body the body prepared by the framework (a {@link ProblemDetail} for RFC 7807 exceptions)
195	     * @param headers the headers to be written to the response
196	     * @param statusCode the selected response status
197	     * @param request the current request
198	     * @return A {@link ResponseEntity} whose body is a fully populated {@link ProblemDetail}.
199	     */
200	    @Override
201	    protected ResponseEntity<Object> handleExceptionInternal(Exception ex, Object body,
202	            HttpHeaders headers, HttpStatusCode statusCode, WebRequest request) {
203	        HttpStatus status = HttpStatus.valueOf(statusCode.value());
204	        ProblemDetail detail = (body instanceof ProblemDetail problemDetail)
205	            ? problemDetail
206	            : ProblemDetail.forStatus(status);
207	        detail.setType(URI.create(requestUrl(request)));
208	        detail.setTitle(ex.getClass().getSimpleName());
209	        if (detail.getDetail() == null) {
210	            detail.setDetail(status.is5xxServerError() ? ERROR_UNEXPECTED : ERROR_INVALID_REQUEST);
211	        }
212	        Map<String, Object> properties = detail.getProperties();
213	        if (properties == null || !properties.containsKey("timestamp")) {
214	            detail.setProperty("timestamp", Instant.now());
215	        }
216	        if (properties == null || !properties.containsKey("schemaValidationErrors")) {
217	            detail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
218	        }
219	        if (status.is4xxClientError()) {
220	            logger.debug("Request rejected ({}) at {}: {}", status.value(), request.getDescription(false), ex.getMessage());
221	        }
222	        return super.handleExceptionInternal(ex, detail, headers, statusCode, request);
223	    }
224	
225	    /**
226	     * Resolves the full request URL used as the problem {@code type}, mirroring the custom handlers that
227	     * build it from the {@link HttpServletRequest}.
228	     *
229	     * @param request the current request
230	     * @return the request URL, or the request description when it cannot be resolved as a servlet request
231	     */
232	    private String requestUrl(WebRequest request) {
233	        if (request instanceof ServletWebRequest servletWebRequest) {
234	            return servletWebRequest.getRequest().getRequestURL().toString();
235	        }
236	        return request.getDescription(false);
237	    }
238	
239	    /**
240	     * Handles {@link InvalidOwnerFieldsException} thrown when an owner payload is missing or blank in
241	     * one or more required fields. Responds with a 400 Bad Request whose {@code errors} array lists the
242	     * name of each offending field.
243	     *
244	     * @param e The {@link InvalidOwnerFieldsException} to be handled
245	     * @param request {@link HttpServletRequest} object referring to the current request.
246	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
247	     */
248	    @ExceptionHandler(InvalidOwnerFieldsException.class)
249	    @ResponseBody
250	    public ResponseEntity<ProblemDetail> handleInvalidOwnerFieldsException(InvalidOwnerFieldsException e, HttpServletRequest request) {
251	        logger.debug("Invalid owner fields at {} {}: {}",
252	            request.getMethod(),
253	            request.getRequestURI(),
254	            e.getFields());
255	        HttpStatus status = HttpStatus.BAD_REQUEST;
256	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
257	        detail.setProperty("errors", e.getFields());
258	        return ResponseEntity.status(status).body(detail);
259	    }
260	
261	    /**
262	     * Handles {@link DuplicateOwnerIdentityException} thrown when an owner is created whose derived
263	     * {@code identityKey} — consolidating the normalized telephone, email and household id — exactly
264	     * matches an existing owner's. Responds with a 409 Conflict.
265	     *
266	     * @param e The {@link DuplicateOwnerIdentityException} to be handled
267	     * @param request {@link HttpServletRequest} object referring to the current request.
268	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
269	     */
270	    @ExceptionHandler(DuplicateOwnerIdentityException.class)
271	    @ResponseBody
272	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerIdentityException(DuplicateOwnerIdentityException e, HttpServletRequest request) {
273	        logger.debug("Duplicate owner identity at {} {}: {}",
274	            request.getMethod(),
275	            request.getRequestURI(),
276	            e.getIdentityKey());
277	        HttpStatus status = HttpStatus.CONFLICT;
278	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
279	        detail.setProperty("errors", List.of("identityKey"));
280	        return ResponseEntity.status(status).body(detail);
281	    }
282	
283	    /**
284	     * Handles {@link OwnerCityAtCapacityException} thrown when an owner is created whose city
285	     * already contains the maximum number of owners (compared case-insensitively with collapsed
286	     * whitespace). Responds with a 409 Conflict.
287	     *
288	     * @param e The {@link OwnerCityAtCapacityException} to be handled
289	     * @param request {@link HttpServletRequest} object referring to the current request.
290	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
291	     */
292	    @ExceptionHandler(OwnerCityAtCapacityException.class)
293	    @ResponseBody
294	    public ResponseEntity<ProblemDetail> handleOwnerCityAtCapacityException(OwnerCityAtCapacityException e, HttpServletRequest request) {
295	        logger.debug("Owner city at capacity at {} {}: {}",
296	            request.getMethod(),
297	            request.getRequestURI(),
298	            e.getCity());
299	        HttpStatus status = HttpStatus.CONFLICT;
300	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
301	        detail.setProperty("errors", List.of("city"));
302	        return ResponseEntity.status(status).body(detail);
303	    }
304	
305	    /**
306	     * Handles {@link DailyOwnerLimitReachedException} thrown when an owner is created on a day that
307	     * has already reached the maximum number of owners registered that day (counted by
308	     * {@code registrationDate}). Responds with a 429 Too Many Requests.
309	     *
310	     * @param e The {@link DailyOwnerLimitReachedException} to be handled
311	     * @param request {@link HttpServletRequest} object referring to the current request.
312	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
313	     */
314	    @ExceptionHandler(DailyOwnerLimitReachedException.class)
315	    @ResponseBody
316	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitReachedException(DailyOwnerLimitReachedException e, HttpServletRequest request) {
317	        logger.debug("Daily owner limit reached at {} {}: {}",
318	            request.getMethod(),
319	            request.getRequestURI(),
320	            e.getDate());
321	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
322	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT_REACHED);
323	        return ResponseEntity.status(status).body(detail);
324	    }
325	
326	}
